def sort_students(student_scores):
    """Sort a list of students by total score (descending), Chinese score (descending),
    then student number (ascending)."""
    return sorted(student_scores, key=lambda s: (-s[1], -s[2], s[0]))

def hanoi_double_iterative(n: int) -> int:
    """Return the minimal number of moves needed to transfer n pairs of identical discs
    from pole A to pole C in the double‑disc Towers of Hanoi puzzle, using an iterative
    algorithm."""
    if n < 0:
        raise ValueError("n must be non‑negative")
    moves = 1
    for _ in range(n + 1):
        moves <<= 1   # multiply by 2 iteratively
    return moves - 2
